#!/usr/bin/env node
/**
 * Generate audit/runs/packet-12.4/tagging-diff.md from the three passes — packet 12.4, E024.
 * Do not edit the output by hand; edit this and re-run it.
 */
import fs from 'node:fs';

const RUN = 'audit/runs/packet-12.4';
const read = (p) => JSON.parse(fs.readFileSync(p, 'utf8'));
const p1 = read(`${RUN}/pass1-tags.json`).tags;
const p2 = read(`${RUN}/pass2-tags.json`).tags;
const p3 = read(`${RUN}/pass3-tags.json`).tags;
const merged = read(`${RUN}/agreed-tags.json`);
const oracle = read('audit/raw/spec-items.json');
const wording = new Map(oracle.items.map((r) => [r.id, r.wording]));
const { MODEL_ANSWERS } = await import(`file://${process.cwd()}/data/modelAnswersData.js`);
const byId = new Map(MODEL_ANSWERS.map((a) => [a.id, a]));

const CONTROL = 'negative-externality-tax-8';
const rows = merged.rows;
const econRows = rows.filter((r) => byId.get(r.key)?.subject === 'economics');
const total = (f) => econRows.reduce((n, r) => n + f(r), 0);

const pairs = { '1+2+3': 0, '1+2': 0, '1+3': 0, '2+3': 0 };
const solo = { 1: 0, 2: 0, 3: 0 };
for (const r of econRows) {
  const s = [new Set(p1[r.key] || []), new Set(p2[r.key] || []), new Set(p3[r.key] || [])];
  for (const id of new Set([...s[0], ...s[1], ...s[2]])) {
    const w = s.map((x) => x.has(id));
    const n = w.filter(Boolean).length;
    if (n === 3) pairs['1+2+3']++;
    else if (n === 2) pairs[w[0] && w[1] ? '1+2' : w[0] && w[2] ? '1+3' : '2+3']++;
    else solo[w[0] ? 1 : w[1] ? 2 : 3]++;
  }
}

const propose = (tags) => econRows.reduce((n, r) => n + (tags[r.key] || []).length, 0);
const md = [];
const P = (...l) => md.push(...l);

P('# Three-pass tagging — the Economics model-answer bank');
P('');
P('Packet 12.4, E023/E024. Generated by `node audit/runs/packet-12.4/write-tagging-diff.mjs`; do not');
P('edit by hand. 46 Economics questions across 22 IAL sections, of which 45 arrived untagged.');
P('');
P('**Pass 1** — the packet author, reading each question\'s TEXT ONLY against that topic\'s rows of');
P('`audit/raw/spec-items.json`. Recorded in `pass1-tags.json` before any pass-2 or pass-3 output was');
P('opened.');
P('');
P('**Pass 2** — four separate agents, one per IAL unit. Each was given only its topics\' input files');
P('(`pass2-input/<topic>.json`: `questions[{key, question}]` and `leaves[{id, subtopic, requirement,');
P('wording}]`) and instructed to read nothing else in the repository — not the marks, not the mark');
P('scheme, not the model answer, not another pass. This is the pass packet 12.1 could not run: it had');
P('no agent-spawn tool and fell back to the lexical matcher, and its own escalation asked for this to');
P('be fixed before the method scaled past one section.');
P('');
P('**Pass 3** — `audit/scripts/tag-lexical.mjs`, the deterministic lexical matcher from packet 12.1,');
P('rule unchanged and untuned, run from the same input files.');
P('');
P('**Only tags at least two of the three passes proposed are written.** A tag one pass made alone is');
P('not a tag; it is a line on the review list below.');
P('');
P('| | count |');
P('|---|---|');
P(`| Economics questions through the process | ${econRows.length} |`);
P(`| tags proposed by pass 1 | ${propose(p1)} |`);
P(`| tags proposed by pass 2 | ${propose(p2)} |`);
P(`| tags proposed by pass 3 | ${propose(p3)} |`);
P(`| **agreed by at least two passes, and therefore written** | **${total((r) => r.agreed.length)}** |`);
P(`| of those, unanimous | ${pairs['1+2+3']} |`);
P(`| items now carrying \`specItems\` | ${econRows.filter((r) => r.agreed.length && r.key !== CONTROL).length} written this packet, plus the control |`);
P(`| items left untagged (absent, not \`[]\`) | ${econRows.filter((r) => !r.agreed.length).length} |`);
P('');
P('## Which passes carried each written tag — read this before quoting the agreement rate');
P('');
P('| carried by | tags |');
P('|---|---|');
P(`| all three | ${pairs['1+2+3']} |`);
P(`| pass 1 + pass 2 (pass 3 dissenting) | ${pairs['1+2']} |`);
P(`| pass 1 + pass 3 (pass 2 dissenting) | ${pairs['1+3']} |`);
P(`| pass 2 + pass 3 (pass 1 dissenting) | ${pairs['2+3']} |`);
P('');
P(`**Pass 3 is a weak third instrument on this bank.** It confirms ${pairs['1+2+3']} tags and abstains on most of the`);
P(`rest: ${pairs['1+2']} of the ${total((r) => r.agreed.length)} written tags rest on passes 1 and 2 with pass 3 dissenting, and only`);
P(`${pairs['1+3'] + pairs['2+3']} written tags carry no pass-1 vote. The independence that is actually load-bearing here is`);
P('pass 1 against pass 2. That is a real property of a lexical matcher against a bank whose questions');
P('are written in a teacher\'s words rather than the specification\'s, and it is the same limitation');
P('packet 12.1 recorded; naming it is better than quoting "three instruments agreed" as if all three');
P('had voted.');
P('');
P(`Single-pass proposals, not written: pass 1 alone ${solo[1]}, pass 2 alone ${solo[2]}, pass 3 alone ${solo[3]}.`);
P('');
P('## What pass 3 abstaining actually means — a fourth reader, blind, with controls');
P('');
P('The counts above cannot distinguish two readings of the 69: pass 3 is weak on this bank, or the');
P('two model passes share a blind spot and both proposed the same plausible-but-wrong leaf. Those look');
P('identical from an agreement table, and the second is the failure mode `audit/DECISIONS.md` keeps');
P('recording. So a fourth reader adjudicated a sample of `(question, requirement)` pairs one at a');
P('time, shuffled and unlabelled, with controls it could not see either (`build-adjudication.mjs`,');
P('seed 20260922, verdicts in `adjudication-verdicts.json`, answer key in `adjudication-key.json`).');
P('');
P('| group | pairs | judged "examines" |');
P('|---|---|---|');
P('| **treatment** — written tags carried by passes 1+2 with pass 3 dissenting | 10 | **9** |');
P('| positive control — unanimous written tags | 7 | 7 |');
P('| negative control — leaves of the same topic that no pass proposed | 7 | 0 |');
P('');
P('The controls are what make the treatment row mean anything: an adjudicator that said yes to');
P('everything would have scored 7/7 on the negative control too, and it scored 0. On that evidence the');
P('69 are mostly real tags a lexical matcher could not see, not a shared hallucination, and the');
P('caveat above is a footnote rather than a finding.');
P('');
P('The one rejection is recorded rather than acted on: `econ-j-curve-depreciation-8` →');
P('`ECON-4.3.3-2e` ("The distinction between devaluation and depreciation of a currency"). The');
P('question uses the word "depreciation" but does not ask for the distinction, and the adjudicator is');
P('right that this is the weaker of that item\'s two tags. It stays, because the merge rule was fixed');
P('before any output was read and dropping a tag on a fourth opinion after the fact is exactly the');
P('tuning this method exists to prevent. A later packet may remove it on this evidence.');
P('');
P('## Two places where pass 1 was not blind, disclosed rather than smoothed over');
P('');
P('**Economics 1.3.5.** The packet brief required reading `audit/runs/packet-12.1/tagging-diff.md`,');
P('which prints packet 12.1\'s own pass-1 proposals for the three 1.3.5 questions. So for');
P('`neg-externality-4` and `market-failure-government-intervention-20` this session\'s pass 1 had seen');
P('an earlier pass 1\'s answer. It matters only where pass 1 is decisive: every tag written on those');
P('two items also carries a pass-2 vote, and the one tag pass 1 held alone');
P('(`ECON-1.3.5-1b-1` on `neg-externality-4`) was **not** written.');
P('');
P('**Economics 3.3.1.** The unit-3 pass-2 agent\'s completion summary reached this session before pass');
P('1 had been written for that topic, and it named its conclusion (both questions empty, because');
P('economies of scale is not in 3.3.1). Pass 1 then read the 3.3.1 leaf list and reached the same');
P('conclusion, so the two are not independent on those two items. Neither carries a written tag in');
P('either pass, so nothing rests on it — but a pass-2 agent should be told to return a bare count.');
P('');
P('## The control');
P('');
P(`\`${CONTROL}\` was already tagged by packet 12.1 (\`ECON-1.3.5-2c-3\`, \`ECON-1.3.5-2d-2\`), agreed there`);
P('by an author pass and the lexical matcher. It was run through all three passes here as an A/B');
P('against a known result and its `specItems` were **not** rewritten — packet 12.1 owns them.');
P('');
const c = rows.find((r) => r.key === CONTROL);
const cs = [new Set(p1[CONTROL]), new Set(p2[CONTROL]), new Set(p3[CONTROL])];
P('| id | pass 1 | pass 2 | pass 3 | written by 12.1 |');
P('|---|---|---|---|---|');
for (const id of [...new Set([...cs[0], ...cs[1], ...cs[2]])].sort()) {
  const was = (byId.get(CONTROL).specItems || []).includes(id);
  P(`| \`${id}\` | ${cs[0].has(id) ? 'Y' : '—'} | ${cs[1].has(id) ? 'Y' : '—'} | ${cs[2].has(id) ? 'Y' : '—'} | ${was ? 'yes' : 'no'} |`);
}
P('');
P('Both of packet 12.1\'s tags are re-derived unanimously, which is the result that would have been');
P('reported had they disagreed. The three-pass process also agrees on three leaves the two-pass');
P('process missed (`1a`, `2b`, `2d-3`), each of them a pass-1-plus-pass-2 agreement that a lexical');
P('matcher cannot see — the specific blind spot 12.1 escalated. They are available to a later packet;');
P('this one did not take them, because rewriting another packet\'s verified output is not a data fix.');
P('');
P('## Items left untagged');
P('');
for (const r of econRows.filter((x) => !x.agreed.length)) {
  const a = byId.get(r.key);
  P(`### \`${r.key}\` — ${a.sectionNumber}, ${a.commandWord} ${a.marks}`);
  P('');
  P(`> ${a.question}`);
  P('');
  P(`- agreed: **none — left untagged (\`specItems\` absent, not \`[]\`)**`);
  for (const d of r.dissent) P(`- pass ${d.pass} only (review): \`${d.id}\` — ${wording.get(d.id) || ''}`);
  P('');
}
P('`economies-scale-4` and `econ-diseconomies-scale-8` are not a tagging gap. Economies and');
P('diseconomies of scale do not appear anywhere in IAL Economics 3.3.1\'s 30 leaves — they are 3.3.2');
P('(`ECON-3.3.2-3a` to `3f`). Both questions sit on the 3.3.1 page and examine 3.3.2, so no honest tag');
P('exists for them here and `/economics/types-sizes-businesses-model-answers` still reads 0.0%. Pass 1');
P('and pass 2 reached this independently of the merge rule. Moving the two items to the');
P('revenue-costs-profits page, or writing 3.3.1 questions, is a content decision and is escalated, not');
P('taken here.');
P('');
P('## Per question');
P('');
P('Every Economics question, its written tags, and every proposal a single pass made alone.');
P('');
const topics = [...new Set(econRows.map((r) => byId.get(r.key).sectionNumber))].sort();
for (const topic of topics) {
  const items = econRows.filter((r) => byId.get(r.key).sectionNumber === topic);
  P(`### ${topic} — ${byId.get(items[0].key).sectionTitle}`);
  P('');
  for (const r of items) {
    const a = byId.get(r.key);
    P(`**\`${r.key}\`** (${a.commandWord} ${a.marks})${r.key === CONTROL ? ' — the control, not rewritten' : ''}`);
    P('');
    P(`- proposed: pass 1 ${r.counts[0]}, pass 2 ${r.counts[1]}, pass 3 ${r.counts[2]}`);
    P(`- written: ${r.agreed.length ? r.agreed.map((i) => `\`${i}\``).join(', ') : '**none**'}`);
    if (r.partial.length) {
      P(`- of those, on two passes only: ${r.partial.map((x) => `\`${x.id}\` (${x.passes.join('+')})`).join(', ')}`);
    }
    if (r.dissent.length) {
      P(`- proposed by one pass and NOT written: ${r.dissent.map((x) => `\`${x.id}\` (pass ${x.pass})`).join(', ')}`);
    }
    P('');
  }
}
P('## What the disagreements say');
P('');
P('The direction of disagreement is the same one packet 12.1 recorded, and it is worth restating with');
P('a second instrument in the room. Pass 3 is lexical: it cannot tag a question that examines a leaf in');
P('other words, so a question whose wording avoids the specification\'s own vocabulary comes back empty');
P('from it. Pass 2 is the opposite — it reads for sense and proposes more (it proposed the most tags of');
P('the three), including whole requirement sets where a question asks for "two factors" without naming');
P('which two. Pass 1 declined those on principle: a question that could be answered from any two of');
P('five leaves does not examine a particular one.');
P('');
P('That disagreement is where the merge rule earns its keep. `barriers-development-4` is the clearest');
P('case: pass 1 proposed nothing, and five tags were written anyway because passes 2 and 3 — which');
P('share no code, no prompt and no author — agreed on them. `globalisation-definition-4` is the mirror');
P('image: pass 2 proposed five, nobody else proposed any, and it stays untagged.');
P('');
P('An untagged question is visible to `npm run spec-coverage` and reads on the page as a floor. A');
P('wrongly tagged one is invisible, and would inflate the coverage number permanently.');
P('');
fs.writeFileSync(`${RUN}/tagging-diff.md`, `${md.join('\n')}\n`);
console.log(`wrote ${RUN}/tagging-diff.md — ${md.length} lines`);
